const ScreenshotIcon = () => (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6">
    <rect x="3" y="4" width="18" height="16" rx="2" />
    <circle cx="8.5" cy="10" r="1.6" />
    <path d="M21 16l-5.5-5.5a2 2 0 00-2.8 0L4 19" />
  </svg>
);

const TABS = [
  {
    id: 't1', label: '01 Track', title: 'Track',
    text: 'See where your brand ranks across ChatGPT, Gemini, Perplexity, Copilot, and Google for the prompts that matter to your business.',
    fig: 'chatgpt.com · cited at #2 for "best [category] in Singapore"',
    caption: 'Track tab: ranking list across ChatGPT, Gemini, Perplexity, Copilot & Google for your tracked prompts',
  },
  {
    id: 't2', label: '02 Analyze', title: 'Analyze',
    text: 'See what helps competitors gain visibility and where your brand needs improvement. Find content gaps, missing schema, weak citations, and other issues that may affect your visibility.',
    fig: '3 competitors outrank you on 12 tracked prompts',
    caption: 'Analyze tab: side-by-side competitor comparison, content gaps highlighted',
  },
  {
    id: 't3', label: '03 Plan & Create', title: 'Plan & Create',
    text: 'Create your content calendar and prepare posts, reels, and blogs based on your brand and priorities.',
    fig: 'Next 7 days: 5 posts · 1 reel · 1 blog — drafted',
    caption: 'Plan & Create tab: 30-day content calendar with drafted posts, reels and blogs',
  },
  {
    id: 't4', label: '04 Audit', title: 'Audit',
    text: 'Run technical AEO and SEO audits to find issues on your website. Some technical issues can be fixed automatically.',
    fig: '14 issues found · 9 fixed automatically',
    caption: 'Audit tab: issue list with severity tags and an auto-fixed status per item',
  },
  {
    id: 't5', label: '05 Agent', title: 'Agent',
    text: 'The AI agent connects the workflow — from auditing and fixing issues to managing content and publishing.',
    fig: 'Running since Aug 2026 · no manual steps this week',
    caption: 'Agent tab: activity timeline showing recent automated actions',
  },
];

export default function HowItWorks() {
  return (
    <section id="how" style={{ background: 'var(--white)', borderBlock: '1px solid var(--border)' }}>
      <div className="wrap">
        <div className="head">
          <span className="eyebrow">How it works</span>
          <h2>The whole loop, in one workspace.</h2>
          <p>Track, analyze, plan, audit, and automate your marketing work from one place.</p>
        </div>
        <div className="tabs">
          {TABS.map((t, i) => (
            <input key={t.id} className="tab-input" type="radio" name="tabs" id={t.id} defaultChecked={i === 0} />
          ))}
          <div className="tab-labels">
            {TABS.map((t) => <label htmlFor={t.id} key={t.id}>{t.label}</label>)}
          </div>
          <div className="tab-panels">
            {TABS.map((t, i) => (
              <div className={`tab-panel panel${i + 1}`} key={t.id}>
                <div>
                  <h4>{t.title}</h4>
                  <p>{t.text}</p>
                  <p className="fig" style={{ marginTop: 10 }}>{t.fig}</p>
                </div>
                <div className="tab-visual img-ph ph-16x10">
                  <span className="tag-ph">Screenshot</span>
                  <ScreenshotIcon />
                  <span>{t.caption}</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}
